'use client'

import { useState } from 'react'

export interface QAItem {
  q: string
  a: string
}

interface QASectionProps {
  items: QAItem[]
}

const STYLE = { fontFamily: 'var(--font-pixel, monospace)' } as const

export default function QASection({ items }: QASectionProps) {
  const [expanded, setExpanded] = useState<number | null>(null)

  function toggle(idx: number) {
    setExpanded((prev) => (prev === idx ? null : idx))
  }

  return (
    <section>
      <h3 className="pixel-section-header">■ 100の質問 Q&amp;A</h3>

      <div>
        {items.map((item, idx) => {
          const isOpen = expanded === idx
          const rowBg = idx % 2 === 0
            ? 'rgba(8, 6, 20, 0.70)'
            : 'rgba(12, 8, 28, 0.70)'

          return (
            <div
              key={idx}
              style={{
                borderBottom: '1px solid rgba(64,232,255,0.10)',
                borderLeft: isOpen ? '3px solid #38ff78' : '3px solid transparent',
              }}
            >
              {/* Question row */}
              <button
                onClick={() => toggle(idx)}
                className="w-full flex items-center gap-2 px-3 py-2 text-left cursor-pointer"
                style={{
                  ...STYLE,
                  background: isOpen ? 'rgba(16, 6, 32, 0.90)' : rowBg,
                }}
                aria-expanded={isOpen}
              >
                {/* Line number */}
                <span
                  style={{
                    fontSize: 10,
                    color: '#40e8ff',
                    minWidth: 22,
                    textShadow: '0 0 5px rgba(64,232,255,0.60)',
                    letterSpacing: '0.04em',
                    flexShrink: 0,
                  }}
                >
                  {String(idx + 1).padStart(2, '0')}
                </span>

                {/* Question text */}
                <span
                  className="flex-1 text-xs truncate"
                  style={{
                    color: isOpen ? '#d0c8f0' : '#9888b8',
                    lineHeight: '1.8',
                  }}
                >
                  {item.q}
                </span>

                {/* Arrow */}
                <span
                  style={{
                    fontSize: 10,
                    color: isOpen ? '#38ff78' : '#ff40c0',
                    textShadow: isOpen
                      ? '0 0 6px rgba(56,255,120,0.70)'
                      : '0 0 6px rgba(255,64,192,0.55)',
                    flexShrink: 0,
                  }}
                >
                  {isOpen ? '▼' : '▶'}
                </span>
              </button>

              {/* Answer (expanded) */}
              {isOpen && (
                <div
                  className="px-3 py-2"
                  style={{
                    background: 'rgba(6, 18, 8, 0.85)',
                    borderTop: '1px solid rgba(56,255,120,0.20)',
                    ...STYLE,
                  }}
                >
                  <p
                    className="text-xs whitespace-pre-wrap"
                    style={{
                      color: '#38ff78',
                      lineHeight: '1.9',
                      textShadow: '0 0 4px rgba(56,255,120,0.40)',
                      paddingLeft: 26, // align with question text
                    }}
                  >
                    <span style={{ color: '#38ff7888' }}>{'>'} </span>
                    {item.a}
                  </p>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </section>
  )
}
